 const head=new THREE.Group();head.position.y=1.72;body.add(head);box(.36,.4,.34,skin,0,0,0,head);
 if(isPlayer){box(.41,.2,.39,material('#3b4940',.2,.65),0,.16,0,head);box(.35,.09,.045,material('#182f30',.5,.2),0,.01,.19,head);box(.5,.48,.11,material('#303f36'),0,1.22,.2,body);for(let i=-1;i<=1;i++)box(.11,.16,.08,material('#8b8860'),i*.14,1.13,.29,body);box(.4,.48,.22,material('#3a493a'),0,1.2,-.26,body);}
 else{for(const x of [-.095,.095])box(.07,.055,.03,material('#d5e9a3',.1,.2,type==='runner'?'#e68131':'#99bd55'),x,.04,.18,head);box(.13,.035,.03,material('#263c32'),0,-.1,.18,head);box(.1,.22,.01,material('#514035'),.11,1.25,.175,body);}
 const legs=[],arms=[];
 for(const s of [-1,1]){const leg=new THREE.Group();leg.position.set(s*.16,.83,0);body.add(leg);box(.2,.62,.22,pants,0,-.3,0,leg);box(.23,.17,.35,boots,0,-.66,.05,leg);legs.push(leg);const arm=new THREE.Group();arm.position.set(s*.36,1.45,0);body.add(arm);box(.19,.36,.23,cloth,0,-.15,0,arm);box(.15,.27,.16,skin,0,-.43,0,arm);box(.16,.14,.18,skin,0,-.6,.015,arm);arm.rotation.x=isPlayer?-1.25:-1.07;arm.rotation.z=s*(isPlayer?-.13:-.12);arms.push(arm);}
