function moveEntity(pos,dx,dz,r=.4){if(canMove(pos.x+dx,pos.z,r))pos.x+=dx;if(canMove(pos.x,pos.z+dz,r))pos.z+=dz;}
function rayBox(ox,oz,dx,dz,o,max){let low=0,high=max;for(const [v,d,lo,hi] of [[ox,dx,o.x-o.w/2,o.x+o.w/2],[oz,dz,o.z-o.d/2,o.z+o.d/2]]){if(Math.abs(d)<.0001){if(v<lo||v>hi)return max;}else{let a=(lo-v)/d,b=(hi-v)/d;if(a>b)[a,b]=[b,a];low=Math.max(low,a);high=Math.min(high,b);if(high<low)return max;}}return low>0?low:max;}
function hitDistance(ox,oz,dx,dz,max=36){for(const o of obstacles)max=Math.min(max,rayBox(ox,oz,dx,dz,o,max));return max;}
const sparkGeometry=new THREE.BoxGeometry(.06,.06,.06);
