const mapCtx=$('minimap').getContext('2d');function drawMap(){const c=mapCtx;c.clearRect(0,0,180,180);c.strokeStyle='#769e8d25';c.lineWidth=1;for(let i=0;i<=180;i+=30){c.beginPath();c.moveTo(i,0);c.lineTo(i,180);c.moveTo(0,i);c.lineTo(180,i);c.stroke();}const scale=3.4;c.fillStyle='#78908360';for(const o of obstacles)c.fillRect(90+(o.x-o.w/2)*scale,90+(o.z-o.d/2)*scale,o.w*scale,o.d*scale);for(const e of enemies){if(e.dead)continue;c.fillStyle=e.type==='brute'?'#ffad67':'#e37358';c.beginPath();c.arc(90+e.pos.x*scale,90+e.pos.z*scale,e.type==='brute'?3:2,0,TAU);c.fill();}if(net.active)for(const p of net.room.players){if(p.id===net.selfId)continue;c.fillStyle=PLAYER_COLORS[p.slot];c.beginPath();c.arc(90+p.x*scale,90+p.z*scale,3,0,TAU);c.fill();}c.save();c.translate(90+player.pos.x*scale,90+player.pos.z*scale);c.rotate(-player.angle);c.fillStyle='#e0f39d';c.beginPath();c.moveTo(0,5);c.lineTo(-3,-3);c.lineTo(3,-3);c.closePath();c.fill();c.restore();}
