// Multiplayer uses an authoritative server; the local renderer predicts movement only.
function networkStatus(message){$('network-status').textContent=message;$('network-status').classList.toggle('hidden',!message);}
function clearNetworkScene(){for(const e of [...enemies])removeEnemy(e);for(const p of pickups)scene.remove(p.group);pickups.length=0;for(const p of particles)scene.remove(p.mesh);particles.length=0;for(const t of tracers){scene.remove(t.line);t.line.geometry.dispose();t.line.material.dispose();}tracers.length=0;}
function showNetworkSetup(){if(net.active)return;$('network-setup').classList.remove('hidden');$('connection-error').textContent='';$('player-name').focus();}
function enableConnectButtons(enabled){$('create-room').disabled=!enabled;$('join-room').disabled=!enabled;}
function beginNetwork(type){if(location.protocol==='file:'){ $('connection-error').textContent='Кооператив работает на сайте игры. Для файла доступна одиночная игра.';return;}const name=$('player-name').value.trim()||'Выживший';const code=$('room-code').value.trim().toUpperCase();if(type==='join'&&!/^[A-F0-9]{10}$/.test(code)){$('connection-error').textContent='Введи 10 символов кода из приглашения.';return;}try{localStorage.setItem('dead-signal-name',name);}catch{}$('connection-error').textContent='';enableConnectButtons(false);initAudio();net.transport.connect({type,name,...(type==='join'?{code}:{})});}
function welcomeNetwork(data){const resumed=net.active;net.active=true;net.selfId=data.id;document.body.classList.add('networked');$('network-setup').classList.add('hidden');enableConnectButtons(true);const u=new URL(location.href);u.searchParams.set('room',data.code);history.replaceState(null,'',u);if(!resumed){clearNetworkScene();net.shownWave=0;net.upgradeWave=0;net.phase=null;player.pos.set(0,0,5);hero.group.position.copy(player.pos);hero.group.rotation.x=0;hero.body.rotation.x=0;net.down=false;$('restart').disabled=false;setScreen('lobby');}else toast('Связь восстановлена');}
function leaveNetwork(showMenu=true){net.transport.stop();net.active=false;net.room=null;net.selfId=null;net.phase=null;net.shownWave=0;net.upgradeWave=0;net.down=false;net.authority=null;clearNetworkScene();for(const r of net.remotes.values()){scene.remove(r.group);scene.remove(r.shadow);r.shadow.material.dispose();r.label.remove();}net.remotes.clear();document.body.classList.remove('networked');$('team-panel').replaceChildren();for(const id of ['coop-lobby','downed','network-setup','network-status'])$(id).classList.add('hidden');$('touch-revive').classList.add('hidden');$('pause').querySelector('p').textContent='Квартал подождёт. Соберись с силами.';$('restart').disabled=false;$('restart').querySelector('span').textContent='ЕЩЁ ОДНА НОЧЬ';document.querySelector('.upgrade-note').textContent='Здоровье +20 · Магазин пополнен · Время остановлено';hero.body.rotation.x=0;hero.group.visible=true;const u=new URL(location.href);u.searchParams.delete('room');history.replaceState(null,'',u);if(showMenu)menu();}
function networkFailed(message){enableConnectButtons(true);networkStatus('');if(net.active){leaveNetwork();showNetworkSetup();}else $('network-setup').classList.remove('hidden');$('connection-error').textContent=message;}
net.transport=new GameConnection({status:networkStatus,welcome:welcomeNetwork,state:applyNetworkState,events:networkEvents,error:message=>{if(net.active)toast(message);else $('connection-error').textContent=message;},failed:networkFailed});
