 if(first||data.phase==='lobby'||data.phase==='upgrade'||oldPhase==='ended'){player.pos.set(me.x,0,me.z);hero.group.position.copy(player.pos);}Object.assign(player,{health:me.health,maxHealth:me.maxHealth,ammo:me.ammo,mag:me.mag,reload:me.reload,reloadDuration:me.reloadDuration,dashCooldown:me.dashCooldown,speed:me.speed});net.down=me.down;elapsed=data.elapsed;wave=data.wave;total=data.total;score=data.score;kills=data.kills;combo=0;
 const ids=new Set();for(const p of data.players){if(p.id===net.selfId)continue;ids.add(p.id);let r=net.remotes.get(p.id);if(!r){r=character(true);r.shadow=blob();r.label=document.createElement('div');r.label.className='remote-label';r.label.style.borderColor=PLAYER_COLORS[p.slot];$('remote-labels').appendChild(r.label);box(.25,.06,.27,material(PLAYER_COLORS[p.slot],.1,.5),0,1.96,0,r.body);r.group.position.set(p.x,0,p.z);r.flash=0;net.remotes.set(p.id,r);}r.target=p;r.label.textContent=p.name+(p.down?' · НУЖНА ПОМОЩЬ':!p.connected?' · НЕТ СВЯЗИ':'');r.label.classList.toggle('down',p.down);}
